fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> String {
    // Promote to a larger integer type to avoid overflow
    let p1 = a as i32;
    let t1 = b as i32;
    let p2 = c as i32;
    let t2 = d as i32;

    // Compute each participant's score using integer arithmetic:
    // S = max(3 * P / 10, P - P * T / 250)
    let score1 = std::cmp::max(3 * p1 / 10, p1 - (p1 * t1) / 250);
    let score2 = std::cmp::max(3 * p2 / 10, p2 - (p2 * t2) / 250);

    // Compare and return the appropriate result
    if score1 > score2 {
        String::from("Misha")
    } else if score2 > score1 {
        String::from("Vasya")
    } else {
        String::from("Tie")
    }
}

